@icontract.ensure(
    lambda result: 
        result is None or isinstance(result, Node)
)
@icontract.ensure(
    lambda result, child: 
        not child is None or result is None
)
@icontract.ensure(
    lambda result, root, child:
        result is (
            None
            if root is None or child is None
            else next(
                (
                    node
                    for node in root.levelorder
                    if node.left is child or node.right is child
                ),
                None,
            )
        )
)
